def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n.

    Raises ValueError if n is negative or not a perfect square.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("expected an int, got %r" % (n,))
    if n < 0:
        raise ValueError("negative input")
    r = _isqrt(n)
    if r * r != n:
        raise ValueError("%d is not a perfect square" % n)
    return r


def _isqrt(n):
    """Exact integer square root (floor), via Newton's method in pure ints."""
    if n == 0:
        return 0
    x = 1 << ((n.bit_length() + 1) // 2)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    while x * x > n:
        x -= 1
    return x
